  { code: 'LDZA', name: 'Zagreb (Croacia) - LDZA' },
  { code: 'EKCH', name: 'Copenhague (Dinamarca) - EKCH' },
  { code: 'EHAM', name: 'Ámsterdam (Países Bajos) - EHAM' },
  // Asia
  { code: 'VIDP', name: 'Delhi (India) - VIDP' },
  { code: 'OSDI', name: 'Damasco (Siria) - OSDI' },
  { code: 'OERK', name: 'Riad (Arabia Saudita) - OERK' },
  { code: 'OMDB', name: 'Dubái (EAU) - OMDB' },
  { code: 'OAKB', name: 'Kabul (Afganistán) - OAKB' },
  { code: 'OOMS', name: 'Mascate (Omán) - OOMS' },
  { code: 'OYSN', name: 'Saná (Yemen) - OYSN' },
  { code: 'OPKC', name: 'Karachi (Pakistán) - OPKC' },
  { code: 'UBBB', name: 'Bakú (Azerbaiyán) - UBBB' },
  { code: 'OJAI', name: 'Amán (Jordania) - OJAI' },
];

const PRODUCTOS = [
  { id: 'ELEC001', name: 'Laptop Lenovo ThinkPad', peso: 2.5, categoria: 'Electrónica' },
  { id: 'ELEC002', name: 'iPhone 15 Pro', peso: 0.2, categoria: 'Electrónica' },
  { id: 'ELEC003', name: 'Monitor Samsung 27"', peso: 4.8, categoria: 'Electrónica' },
  { id: 'ROPA001', name: 'Camisa Polo Ralph Lauren', peso: 0.3, categoria: 'Ropa' },
  { id: 'ROPA002', name: 'Jeans Levi\'s 501', peso: 0.7, categoria: 'Ropa' },
  { id: 'LIBR001', name: 'Enciclopedia Britannica', peso: 3.2, categoria: 'Libros' },
  { id: 'DECO001', name: 'Jarrón de Cerámica', peso: 1.8, categoria: 'Decoración' },
  { id: 'DECO002', name: 'Cuadro Enmarcado', peso: 2.1, categoria: 'Decoración' },
  { id: 'MED001', name: 'Medicamentos Especiales', peso: 0.5, categoria: 'Medicinas' },
  { id: 'DOC001', name: 'Documentos Legales', peso: 0.1, categoria: 'Documentos' }
];

const PEDIDOS_EJEMPLO = [
  {
    id: 'ORD-20240915-0001',
    cliente: 'Juan Pérez',
    email: 'juan.perez@email.com',
    telefono: '+51 999 123 456',
    origen: 'SPIM',
    destino: 'SKBO',
    producto: 'ELEC001',
    cantidad: 1,
    prioridad: 'Normal',
    status: 'Hecho',
    createdAt: '2024-09-15T08:30:00.000Z',
    notas: 'Entrega urgente'
  },
  {
    id: 'ORD-20240915-0002',
    cliente: 'María González',
    email: 'maria.gonzalez@empresa.com',
    telefono: '+57 300 456 789',
    origen: 'EBCI',
    destino: 'SPIM',
    producto: 'ROPA001',
    cantidad: 5,
    prioridad: 'Urgente',
    status: 'En curso',
    createdAt: '2024-09-15T10:15:00.000Z',
    notas: ''
  },
  {
    id: 'ORD-20240915-0003',
    cliente: 'Carlos Rodriguez',
    email: 'carlos.r@gmail.com',
    telefono: '+34 666 789 012',
    origen: 'EDDI',
    destino: 'UBBB',
    producto: 'MED001',
    cantidad: 2,
    prioridad: 'Crítico',
    status: 'Cancelado',
    createdAt: '2024-09-15T14:22:00.000Z',
    notas: 'Producto descontinuado'
  },
  {
    id: 'ORD-20240915-0004',
    cliente: 'Ana Silva',
    email: 'ana.silva@tech.com',
    telefono: '+55 11 98765 4321',
    origen: 'SBBR',
    destino: 'EHAM',
    producto: 'ELEC003',
    cantidad: 1,
    prioridad: 'Normal',
    status: 'En curso',
    createdAt: '2024-09-15T16:45:00.000Z',
    notas: 'Frágil - manejar con cuidado'
  }
];

const initialForm = {
  cliente: '',
  email: '',
  telefono: '',
  origen: 'SPIM',
  destino: 'SKBO',
  producto: 'ELEC001',
  cantidad: 1,
  prioridad: 'Normal',
  notas: ''
};

const Pedidos = () => {
  const [form, setForm] = useState(initialForm);
  const [errors, setErrors] = useState({});
  const [orders, setOrders] = useState(PEDIDOS_EJEMPLO);
  const [filter, setFilter] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('morapack_orders');
    if (saved) {
      setOrders(JSON.parse(saved));
    } else {
      // Si no hay datos guardados, usar los pedidos de ejemplo
      setOrders(PEDIDOS_EJEMPLO);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('morapack_orders', JSON.stringify(orders));
  }, [orders]);

  const resetForm = () => { setForm(initialForm); setErrors({}); };

  const generateId = () => {
    const now = new Date();
    const y = now.getFullYear();
    const m = String(now.getMonth() + 1).padStart(2, '0');
    const d = String(now.getDate()).padStart(2, '0');
    const n = String(Math.floor(Math.random() * 10000)).padStart(4, '0');
    return `ORD-${y}${m}${d}-${n}`;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  const handleImportFile = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const importedOrders = JSON.parse(event.target.result);
          if (Array.isArray(importedOrders)) {
            setOrders(prev => [...importedOrders, ...prev]);
            alert(`Se importaron ${importedOrders.length} pedidos correctamente`);
          } else {
            alert('El formato del archivo no es válido');
          }
        } catch (error) {
          alert('Error al leer el archivo. Asegúrate de que sea un archivo JSON válido.');
        }
      };
      reader.readAsText(file);
    }
    e.target.value = ''; // Reset input
  };

  const exportOrders = () => {
    const dataStr = JSON.stringify(orders, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'pedidos_morapack.json';
    link.click();
    URL.revokeObjectURL(url);
  };

  const validate = () => {
    const v = {};
    if (!form.cliente.trim()) v.cliente = 'Requerido';
    if (!form.email.match(/^\S+@\S+\.\S+$/)) v.email = 'Email inválido';
    if (form.origen === form.destino) v.destino = 'Destino no puede ser igual a origen';
    const cantidad = parseInt(form.cantidad, 10); 
    if (!(cantidad >= 1)) v.cantidad = 'Mínimo 1';
    setErrors(v);
    return Object.keys(v).length === 0;
  };

  const submit = (e) => {
    e.preventDefault();
    if (!validate()) return;
    const id = generateId();
    const selectedProduct = PRODUCTOS.find(p => p.id === form.producto);
    const order = { 
      id, 
      status: 'Pendiente', 
      createdAt: new Date().toISOString(),
      pesoTotal: selectedProduct.peso * form.cantidad,
      ...form 
    };
    setOrders(prev => [order, ...prev]);
    resetForm();
  };

  const remove = (id) => setOrders(prev => prev.filter(o => o.id !== id));

  const updateStatus = (id, newStatus) => {
    setOrders(prev => prev.map(o => 
      o.id === id ? { ...o, status: newStatus } : o
    ));
  };

  const totalFiltrado = useMemo(() => orders.filter(o =>
    [o.id, o.cliente, o.email, o.origen, o.destino, o.status].join(' ').toLowerCase().includes(filter.toLowerCase())
  ), [orders, filter]);

  return (
    <div className="pedidos-page">
      <div className="pedidos-layout">
        <section className="form-section">
          <h2><i className="fas fa-clipboard-list"></i> Ingresar Pedido</h2>
          <form className="pedido-form" onSubmit={submit}>
            <div className="grid two">
              <div className="field">
                <label>Cliente *</label>
                <input name="cliente" value={form.cliente} onChange={handleChange} placeholder="Nombre o razón social" />
                {errors.cliente && <small className="error">{errors.cliente}</small>}
              </div>
              <div className="field">
                <label>Email *</label>
                <input name="email" type="email" value={form.email} onChange={handleChange} placeholder="cliente@dominio.com" />
                {errors.email && <small className="error">{errors.email}</small>}
              </div>
            </div>

            <div className="grid three">
              <div className="field">
                <label>Teléfono</label>
                <input name="telefono" value={form.telefono} onChange={handleChange} placeholder="+51 999 999 999" />
              </div>
              <div className="field">
                <label>Origen *</label>
                <select name="origen" value={form.origen} onChange={handleChange}>
                  {AIRPORTS.map(a => <option key={a.code} value={a.code}>{a.name}</option>)}
                </select>
              </div>
              <div className="field">
                <label>Destino *</label>
                <select name="destino" value={form.destino} onChange={handleChange}>
                  {AIRPORTS.map(a => <option key={a.code} value={a.code}>{a.name}</option>)}
                </select>
                {errors.destino && <small className="error">{errors.destino}</small>}
              </div>
            </div>

            <div className="grid three">
              <div className="field">
                <label>Tipo de envío</label>
                <select name="tipoEnvio" value={form.tipoEnvio} onChange={handleChange}>
                  <option>Documento</option>
                  <option>Paquete</option>
                  <option>Carga</option>
                </select>
              </div>
              <div className="field">
                <label>Unidades *</label>
                <input name="unidades" type="number" min="1" value={form.unidades} onChange={handleChange} />
                {errors.unidades && <small className="error">{errors.unidades}</small>}
              </div>
              <div className="field">
                <label>Peso (kg) *</label>
                <input name="pesoKg" type="number" step="0.01" value={form.pesoKg} onChange={handleChange} />
                {errors.pesoKg && <small className="error">{errors.pesoKg}</small>}
              </div>
            </div>

            <div className="grid three">
              <div className="field">
                <label>Largo (cm) *</label>
                <input name="largoCm" type="number" step="0.1" value={form.largoCm} onChange={handleChange} />
              </div>
              <div className="field">
                <label>Ancho (cm) *</label>
                <input name="anchoCm" type="number" step="0.1" value={form.anchoCm} onChange={handleChange} />
              </div>
              <div className="field">
                <label>Alto (cm) *</label>
                <input name="altoCm" type="number" step="0.1" value={form.altoCm} onChange={handleChange} />
                {errors.dim && <small className="error">{errors.dim}</small>}
              </div>
            </div>

            <div className="grid two">
              <div className="field">
                <label>Descripción / Contenido</label>
                <input name="descripcion" value={form.descripcion} onChange={handleChange} placeholder="Descripción del contenido" />
              </div>
              <div className="field">
                <label>Prioridad</label>
                <select name="prioridad" value={form.prioridad} onChange={handleChange}>
                  <option>Normal</option>
                  <option>Urgente</option>
                  <option>Crítico</option>
                </select>
              </div>
            </div>

            <div className="grid three">
              <div className="field">
                <label>Recolección</label>
                <input name="recoleccion" type="datetime-local" value={form.recoleccion} onChange={handleChange} />
              </div>
              <div className="field">
                <label>Entrega límite</label>
                <input name="entregaLimite" type="datetime-local" value={form.entregaLimite} onChange={handleChange} />
                {errors.entregaLimite && <small className="error">{errors.entregaLimite}</small>}
              </div>
              <div className="field">
                <label>Valor declarado (USD)</label>
                <input name="valorDeclarado" type="number" step="0.01" value={form.valorDeclarado} onChange={handleChange} />
              </div>
            </div>

            <div className="grid four">
              <div className="field">
                <label>Empaque</label>
                <select name="empaque" value={form.empaque} onChange={handleChange}>
                  <option>Caja</option>
                  <option>Saco</option>
                  <option>Pallet</option>
                  <option>Otro</option>
                </select>
              </div>
              <div className="field checkbox">
                <label><input type="checkbox" name="refrigerado" checked={form.refrigerado} onChange={handleChange} /> Refrigerado</label>
              </div>
              <div className="field checkbox">
                <label><input type="checkbox" name="peligroso" checked={form.peligroso} onChange={handleChange} /> Material peligroso</label>
              </div>
              <div className="field checkbox">
                <label><input type="checkbox" name="seguro" checked={form.seguro} onChange={handleChange} /> Seguro</label>
              </div>
            </div>

            <div className="field">
              <label>Notas</label>
              <textarea name="notas" rows="3" value={form.notas} onChange={handleChange} placeholder="Instrucciones adicionales" />
            </div>

            <div className="actions">
              <button type="submit" className="btn primary"><i className="fas fa-save"></i> Guardar Pedido</button>
              <button type="button" className="btn" onClick={resetForm}><i className="fas fa-eraser"></i> Limpiar</button>
            </div>
          </form>
        </section>

        <section className="list-section">
          <div className="list-header">
            <h2><i className="fas fa-boxes"></i> Pedidos</h2>
            <input className="search" placeholder="Buscar por ID, cliente, email…" value={filter} onChange={e=>setFilter(e.target.value)} />
          </div>
          <div className="orders-table">
            <div className="table-head">
              <div>ID</div>
              <div>Cliente</div>
              <div>Origen</div>
              <div>Destino</div>
              <div>Unid.</div>
              <div>Peso</div>
              <div>Prioridad</div>
              <div>Estado</div>
              <div></div>
            </div>
            {totalFiltrado.length === 0 && <div className="empty">Sin pedidos</div>}
            {totalFiltrado.map(o => (
              <div className="table-row" key={o.id}>
                <div className="mono">{o.id}</div>
                <div>{o.cliente}</div>
                <div>{o.origen}</div>
                <div>{o.destino}</div>
                <div>{o.unidades}</div>
                <div>{o.pesoKg} kg</div>
                <div><span className={`badge ${o.prioridad.toLowerCase()}`}>{o.prioridad}</span></div>
                <div><span className="badge state">{o.status}</span></div>
                <div className="row-actions"><button className="icon danger" title="Borrar" onClick={()=>remove(o.id)}><i className="fas fa-trash"></i></button></div>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
};

export default Pedidos;
